def blocks(g, sep):
    H=len(g); W=len(g[0])
    rs=[i for i in range(H) if all(v==sep for v in g[i])]
    cs=[j for j in range(W) if all(g[i][j]==sep for i in range(H))]
    def segs(n, seps):
        out=[];s=0
        for e in seps+[n]: out.append((s,e)); s=e+1
        return [(a,b) for a,b in out if b>a]
    return segs(H,rs), segs(W,cs)

